18	export function newClassLink(): string;                                              // https://classroom.example/trial/<random>
19	export async function loadMentors(pool: Pool): Promise<Mentor[]>;                   // with hours ('HH:MM'), ordered by id
20	export async function loadActiveBookings(pool: Pool, from: Date, to: Date): Promise<ActiveBooking[]>;  // from <= starts_at < to
21	export async function bookSlot(pool: Pool, input: BookingInput, now: Date, hooks?: { beforeInsert?: () => Promise<void> }): Promise<BookResult>;
22	export async function getBookingWithMentor(pool: Pool, id: string): Promise<{ booking: Booking; mentor: Mentor } | null>;
23	// src/server/test-db.ts (test-only)
24	export async function expectBookingRulesHold(pool: Pool): Promise<void>;
